\begin{document}
\begin{tikzpicture}
\begin{axis}[
    view={120}{20},
    xlabel=$x$,
    ylabel=$y$,
    zlabel=$z$,
    title={Hyperboloid of one sheet},
    xmin=-4,xmax=6,
    ymin=-4,ymax=6,
    zmin=-6,zmax=2,
    axis equal,
    colormap/viridis,
    samples=50,
    samples y=50,
    domain=-2:2,
    y domain=0:360,
]
