\documentclass[border=10pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.17}
\begin{document}
\begin{tikzpicture}
\begin{axis}[
    axis equal,
    xlabel=$x$,
    ylabel=$z$,
    title={Horizontal traces $y=k$},
    xmin=-6,xmax=6,
    ymin=-6,ymax=2,
    grid=both,
    legend pos=outer north east,
]
\foreach \k/\col in {-2/blue,-1/cyan,1/green,2/orange,3/red}{
\pgfmathsetmacro{\r}{sqrt(2+(\k-1)^2)}
\addplot[\col,thick,domain=0:360,samples=100] ({1+\r*cos(x)},{-2+\r*sin(x)});
}
\addplot[only marks,mark=*,red] coordinates {(1,-2)};
\end{axis}
\end{tikzpicture}
\end{document}

